window.docContents[92].resolve({"/releases/#release-v4___32___0":{"contents":"\n\n* Labels such as \"Fields\" and \"Constructors\" in a rendered declaration are labeled groups. (#880)* The descriptors that block_extension and inline_extension generate are public, so a document that uses an extension resolves its implementation under the module system.\n (#909)* Math written in module docstrings is rendered with KaTeX in the HTML that verso-literate-html produces.\n (#899)* Verso.Method is defined in MultiVerso and re-exported from its former home, which lets Verso:shared build.\n (#903)\n\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes","header":"Verso 4.32.0","id":"/releases/#release-v4___32___0"}});